-- Verified live Zendrop -> God Matters checkout bridge.
-- Retail item prices are supplier item cost +20%, converted at 1 USD = 62.82 PHP on 2026-10-13.
-- Shipping is finalized in secure hosted checkout before payment.
ON CONFLICT(id) DO UPDATE SET slug=excluded.slug,title=excluded.title,description=excluded.description,category=excluded.category,price_cents=excluded.price_cents,currency=excluded.currency,image_url=excluded.image_url,active=1,featured=excluded.featured,supplier_provider=excluded.supplier_provider,supplier_product_id=excluded.supplier_product_id,supplier_variant_id=excluded.supplier_variant_id,supplier_sku=excluded.supplier_sku,supplier_url=excluded.supplier_url,fulfillment_mode='dropship',inventory_mode='supplier',stock_qty=excluded.stock_qty,updated_at=excluded.updated_at,product_kind='dropship',supplier_origin_country=excluded.supplier_origin_country,supplier_cost_hint_cents=excluded.supplier_cost_hint_cents,handling_cents=0,facebook_enabled=1,source_note=excluded.source_note;
